#!/usr/bin/env bash
# Shared intake watcher-shim identity helpers.
# Usage: . bin/fm-intake-lib.sh
set -u

# shellcheck source=bin/fm-x-lib.sh
. "$(dirname -- "${BASH_SOURCE[0]}")/fm-x-lib.sh"

fm_intake_poll_shim_content() {  # <home> <root>
  local home=$1 root=$2
  printf '%s\n' \
    '#!/usr/bin/env bash' \
    '# Auto-generated by fm-bootstrap.sh - intake poll shim.' \
    '# The watcher runs this each check cycle; output becomes a check: wake.' \
    "export FM_HOME=$(printf '%q' "$home")" \
    "exec $(printf '%q' "$root/bin/fm-intake-poll.sh")"
}

fm_intake_poll_shim_valid() {  # <file> <home> <root>
  local file=$1 home=$2 root=$3
  fmx_poll_shim_private_identity_valid "$file" || return 1
  cmp -s "$file" <(fm_intake_poll_shim_content "$home" "$root")
}
